        for c in range(cols):
            if grid[r][c] == 3 and not visited[r][c]:
                comp = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop(0)
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 3 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                components.append(comp)

    # Mark which cells to keep based on component size
    to_keep = set()
    for comp in components:
        # Keep components with size >= 10? Or with certain shape?
        if len(comp) >= 6:
            for (r, c) in comp:
                to_keep.add((r, c))

    # Reconstruct grid with 9s as 3s
    for (r, c) in nine_positions:
        to_keep.add((r, c))

    result = [[0]*cols for _ in range(rows)]
    for (r, c) in to_keep:
